import zones from "./airports.json";

// IATA airport code to IANA time zone, generated by scripts/airports.mjs.
// Separate entry point (`@travelmo/core/airports`): the table is a hundred
// kilobytes and only a booking form needs it, so it loads on demand.
const table: Record<string, string> = zones;

export function airportZone(code: string): string | undefined {
  const key = code.trim().toUpperCase();
  return /^[A-Z]{3}$/.test(key) ? table[key] : undefined;
}
